import { useEffect, useState, type CSSProperties } from "react"
import { Heart } from "lucide-react"
import { cn } from "cn"
import { Button } from "@/components/ui/button"
import styles from "@/components/ui/like-button.module.css"

const petals = [
  [-28, -18, -20, 11], [-8, -36, -12, 13],
  [25, -27, 18, 12], [34, 10, 22, 11], [-24, 26, -18, 10],
]

export function LikeButton({
  defaultLiked = false,
  onLikedChange,
  label = "Like",
  unlikeLabel = "Unlike",
  className,
}: {
  defaultLiked?: boolean
  onLikedChange?: (liked: boolean) => void
  label?: string
  unlikeLabel?: string
  className?: string
}) {
  const [liked, setLiked] = useState(defaultLiked)
  const [burst, setBurst] = useState(0)
  useEffect(() => {
    if (!burst) return
    const timer = setTimeout(() => setBurst(0), 1000)
    return () => clearTimeout(timer)
  }, [burst])
  const action = liked ? unlikeLabel : label

  return (
    <span className={cn(styles.root, className)} data-pointer-feedback="none">
      {burst > 0 && (
        <span key={burst} className={styles.particles} aria-hidden="true">
          {petals.map(([x, y, turn, size], index) => (
            <Heart key={index} className={styles.particle} fill="currentColor" strokeWidth={0}
              style={{ "--heart-x": `${x}px`, "--heart-y": `${y}px`, "--heart-turn": `${turn}deg`, "--heart-size": `${size}px`, "--heart-delay": `${index % 3 * 24}ms` } as CSSProperties} />
          ))}
        </span>
      )}
      <Button type="button" variant="outline" size="icon-lg"
        className={styles.button} data-liked={liked || undefined}
        aria-label={action} aria-pressed={liked}
        onClick={() => {
          const next = !liked
          setLiked(next)
          setBurst(next ? (value) => value + 1 : 0)
          onLikedChange?.(next)
        }}>
        <span className={styles.heart} aria-hidden="true">
          <Heart className={styles.outline} fill="none" />
          <Heart className={styles.fill} fill="currentColor" strokeWidth={0} />
        </span>
      </Button>
    </span>
  )
}

.root {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 56px;
  height: 56px;
  color: #ef3e6e;
  isolation: isolate;
}
.button {
  border-color: transparent !important;
  background: transparent !important;
  color: var(--muted-foreground) !important;
  scale: 1 !important;
}
.button[data-liked] { color: #ef3e6e !important; }
.button::before, .button::after { display: none; }
.button .heart { width: 24px; height: 24px; }
.heart { position: relative; display: block; }
.button .heart .outline, .button .heart .fill {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transition: opacity 200ms ease-out, transform 240ms ease-out, fill-opacity 160ms ease-out;
}
.outline { opacity: 1; fill: currentColor; fill-opacity: 0; }
@media (hover: hover) and (pointer: fine) {
  .button:not([data-liked]):hover .outline { fill-opacity: 0.16; }
}
.fill { color: #ef3e6e; opacity: 0; transform: scale(0.85); }
.button[data-liked] .outline { opacity: 0; }
.button[data-liked] .fill { opacity: 1; transform: scale(1); }
.button[data-liked] .heart { animation: heartPop 420ms cubic-bezier(0.2, 0.8, 0.3, 1.3); }
.particles { position: absolute; inset: 0; pointer-events: none; }
.particle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--heart-size);
  height: var(--heart-size);
  opacity: 0;
  animation: heartScatter 850ms var(--heart-delay) cubic-bezier(0.16, 0.7, 0.3, 1) both;
}
.particle:nth-child(3n) { color: #ff91b1; }
.particle:nth-child(3n + 1) { color: #f25a80; }
@keyframes heartPop {
  0% { transform: scale(0.7); }
  45% { transform: scale(1.22); }
  100% { transform: scale(1); }
}
@keyframes heartScatter {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.25); }
  12% { opacity: 1; }
  65% { opacity: 0.9; }
  100% { opacity: 0; transform: translate(calc(-50% + var(--heart-x)), calc(-50% + var(--heart-y))) rotate(var(--heart-turn)) scale(0.65); }
}
@media (prefers-reduced-motion: reduce) {
  .particles { display: none; }
  .button[data-liked] .heart { animation: none; }
  .button .heart .outline, .button .heart .fill { transition: none; }
}

