import type { CSSProperties } from "react"
import { cn } from "cn"
import styles from "@/components/ui/progressive-blur.module.css"

const layers = [
  { blur: 2, start: 55, end: 72 },
  { blur: 4, start: 65, end: 85 },
  { blur: 8, start: 75, end: 95 },
  { blur: 16, start: 85, end: 100 },
]

export function ProgressiveBlur({ className, src }: { className?: string; src?: string }) {
  return (
    <div className={cn(styles.overlay, className)} aria-hidden="true">
      {layers.map(({ blur, start, end }) => (
        <span key={blur} className={styles.layer} style={{
          "--progressive-blur": `${blur}px`,
          "--blur-start": `${start}%`,
          "--blur-end": `${end}%`,
        } as CSSProperties}>
          {src && <img src={src} alt="" draggable={false} className={styles.image} />}
        </span>
      ))}
    </div>
  )
}

.lift {
  transition: transform 220ms ease-out, box-shadow 220ms ease-out;
}
@media (hover: hover) and (pointer: fine) {
  .hoverTarget:hover .lift {
    transform: translateY(-4px);
    box-shadow: 0 12px 24px rgb(0 0 0 / 18%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .lift { transition: none; }
  .hoverTarget:hover .lift { transform: none; }
}
.frame {
  /* Keep filtered layers and the source image in one rounded compositing mask. */
  -webkit-mask-image: linear-gradient(#fff, #fff);
  mask-image: linear-gradient(#fff, #fff);
}
@supports not (corner-shape: squircle) {
  .frame { clip-path: inset(0 round var(--radius-3xl)); }
}
.overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  overflow: hidden;
}
.layer {
  position: absolute;
  inset: 0;
  -webkit-mask-image: linear-gradient(to bottom, transparent var(--blur-start), #000 var(--blur-end));
  mask-image: linear-gradient(to bottom, transparent var(--blur-start), #000 var(--blur-end));
}
.layer:empty {
  -webkit-backdrop-filter: blur(var(--progressive-blur));
  backdrop-filter: blur(var(--progressive-blur));
}
.image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(var(--progressive-blur));
}

