import { useRef, useState } from "react"
import styles from "@/components/ui/slosh-slider.module.css"

const clamp = (value: number) => Math.max(0, Math.min(100, value))

export function SloshSlider({ label = "Flow", defaultValue = 62, onValueChange }: {
  label?: string
  defaultValue?: number
  onValueChange?: (value: number) => void
} = {}) {
  const [value, setValue] = useState(() => clamp(defaultValue))
  const held = useRef(false)
  const commit = (next: number) => {
    const bounded = clamp(next)
    setValue(bounded)
    onValueChange?.(bounded)
  }
  const readAt = (event: React.PointerEvent<HTMLDivElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect()
    if (bounds.width > 0) commit((event.clientX - bounds.left) / bounds.width * 100)
  }
  const release = () => { held.current = false }
  const handlePosition = `clamp(10px, ${value}%, calc(100% - 10px))`

  return <div className={styles.root}>
    <div className={styles.track} role="slider" tabIndex={0}
      aria-label={label} aria-orientation="horizontal"
      aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(value)}
      onPointerDown={event => {
        if (!event.isPrimary || event.button !== 0) return
        event.preventDefault()
        event.currentTarget.focus()
        event.currentTarget.setPointerCapture(event.pointerId)
        held.current = true
        readAt(event)
      }}
      onPointerMove={event => { if (held.current) readAt(event) }}
      onPointerUp={event => {
        if (held.current) readAt(event)
        release()
      }}
      onPointerCancel={release} onLostPointerCapture={release} onBlur={release}
      onKeyDown={event => {
        const step = event.shiftKey ? 10 : 2
        const next = event.key === "Home" ? 0 : event.key === "End" ? 100
          : event.key === "ArrowRight" || event.key === "ArrowUp" ? value + step
          : event.key === "ArrowLeft" || event.key === "ArrowDown" ? value - step : null
        if (next === null) return
        event.preventDefault()
        commit(next)
      }}>
      <div className={styles.fill} style={{ width: value === 0 ? "0px" : `calc(${handlePosition} + 10px)` }} aria-hidden="true" />
      <div className={styles.knob} style={{ left: handlePosition }} aria-hidden="true" />
    </div>
  </div>
}

/* Slider shape: Copyright (c) 2026 Lorenzo Cabra, MIT.
   Full notice is retained in slosh-slider.tsx. */
.root { width: 192px; max-width: 100%; font-family: var(--font-sans); color: var(--foreground); }
.track {
  position: relative;
  height: 28px;
  border-radius: var(--radius-xl);
  corner-shape: var(--corner-shape);
  background: color-mix(in srgb, var(--foreground) 11%, var(--card));
  overflow: hidden;
  cursor: ew-resize;
  touch-action: none;
}
.track:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--card), 0 0 0 4px color-mix(in srgb, var(--ring) 40%, transparent);
}
/* A 14px circular radius becomes a capsule on this 28px track. */
@supports not (corner-shape: squircle) {
  .track { border-radius: calc(var(--radius-xl) / 2); }
}
/* The blue fill surrounds the white handle with a 4px inset, like Toggle. */
.fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: inherit; corner-shape: inherit; background: var(--primary); }
/* The inset handle remains inside both end stops. The entire track
   receives pointer input so the narrow visual is not the only hit target. */
.knob { position: absolute; top: 4px; bottom: 4px; width: 12px; margin-left: -6px; border-radius: 4px; corner-shape: round; background: var(--primary-foreground); box-shadow: var(--control-thumb-shadow); pointer-events: none; }

.mark { position: relative; display: inline-flex; width: 56px; height: 56px; flex-shrink: 0; color: var(--primary-foreground); }
.disc { display: flex; width: 100%; height: 100%; align-items: center; justify-content: center; border-radius: 50%; corner-shape: round; background: var(--primary); animation: successBounce 420ms ease-out both; }
.mark .check { width: 32px; height: 32px; transform: translate(1px, 2px); }
.check path { stroke-dasharray: 32; stroke-dashoffset: 0; animation: successDraw 650ms cubic-bezier(0.4, 0, 0.2, 1) both; }
.burst, .ray { position: absolute; inset: 0; pointer-events: none; }
.ray::after { content: ""; position: absolute; top: -4px; left: calc(50% - 1px); width: 2px; height: 8px; border-radius: 1px; background: var(--primary); opacity: 0; animation: successBurst 400ms ease-out both; }
.replay { background: transparent !important; border-color: transparent !important; scale: 1 !important; }
.replay::before, .replay::after { display: none; }
@keyframes successDraw { from { stroke-dashoffset: 32; } to { stroke-dashoffset: 0; } }
@keyframes successBounce {
  0% { opacity: 0; transform: scale(0.45); }
  55% { opacity: 1; transform: scale(1.12); }
  78% { transform: scale(0.97); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes successBurst {
  0% { opacity: 0; transform: translateY(0) scaleY(0.4); }
  20% { opacity: 0.8; transform: translateY(-6px) scaleY(1); }
  100% { opacity: 0; transform: translateY(-20px) scaleY(0.4); }
}
