function TabsList({
  className,
  variant = "default",
  sizing = "content",
  size = "default",
  children,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> &
  VariantProps<typeof tabsListVariants>) {
  const listRef = React.useRef<HTMLDivElement>(null)
  const [indicator, setIndicator] = React.useState<{
    left: number
    top: number
    width: number
    height: number
  } | null>(null)

  React.useLayoutEffect(() => {
    const list = listRef.current
    if (!list || variant !== "default") return

    const updateIndicator = () => {
      const active = list.querySelector<HTMLElement>(
        '[data-slot="tabs-trigger"][data-state="active"]'
      )
      if (!active) return
      // The indicator and triggers share the list's layout coordinates. Viewport
      // rectangles include ancestor scaling and would shrink the pill a second time.
      setIndicator({
        left: active.offsetLeft,
        top: active.offsetTop,
        width: active.offsetWidth,
        height: active.offsetHeight,
      })
    }

    const resizeObserver = new ResizeObserver(updateIndicator)
    const observeItems = () => {
      resizeObserver.observe(list)
      list.querySelectorAll<HTMLElement>('[data-slot="tabs-trigger"]').forEach((item) => resizeObserver.observe(item))
    }
    const observer = new MutationObserver(() => {
      observeItems()
      updateIndicator()
    })
    observer.observe(list, {
      subtree: true,
      attributes: true,
      attributeFilter: ["data-state"],
      childList: true,
      characterData: true,
    })
    observeItems()
    updateIndicator()

    return () => {
      observer.disconnect()
      resizeObserver.disconnect()
    }
  }, [variant, sizing, size])

  return (
    <TabsPrimitive.List
      ref={listRef}
      data-slot="tabs-list"
      data-variant={variant}
      data-sizing={sizing}
      data-size={size}
      className={cn("relative", tabsListVariants({ variant, sizing, size }), className)}
